starter.css:
table.preise { border-collapse: collapse; }
.preise td, .preise th { border: 1px solid #888; padding: 6px 12px; }
.preise th { background-color: #f0e6d6; }

header { background-color: #ffe0b3; padding: 10px; }
nav { background-color: #cde8ff; padding: 10px; }
main { background-color: #e8f7e8; padding: 10px; min-height: 60px; }
footer { background-color: #e6e6e6; padding: 10px; font-size: 14px; }
.wichtig { color: #c0392b; font-weight: bold; }
